message:
Running command: set -euxo pipefail; SUDO=""; if [ "$(id -u)" -ne 0 ]; then SUDO="sudo"; fi; 
# Ensure sudo is installed if possible
if ! command -v sudo >/dev/null 2>&1; then if command -v apt-get >/dev/null 2>&1; then $SUDO apt-get update && $SUDO apt-get install -y sudo; elif command -v yum >/dev/null 2>&1; then $SUDO yum install -y sudo; elif command -v apk >/dev/null 2>&1; then $SUDO apk add --no-cache sudo; fi; fi;

for u in devtest1 devtest2 qa_sudo; do if id -u "$u" >/dev/null 2>&1; then echo "User $u already exists"; else $SUDO useradd -m -s /bin/bash "$u"; fi; echo "$u:test123" | $SUDO chpasswd; done;

sudo_group=""; if getent group sudo >/dev/null 2>&1; then sudo_group="sudo"; elif getent group wheel >/dev/null 2>&1; then sudo_group="wheel"; fi; if [ -n "$sudo_group" ]; then $SUDO usermod -aG "$sudo_group" qa_sudo; else echo "No sudo/wheel group found; configuring sudoers entry for qa_sudo"; fi;

# Always ensure passwordless sudo for automation
if [ -d /etc/sudoers.d ]; then tmp=$(mktemp); printf "qa_sudo ALL=(ALL) NOPASSWD:ALL\n" > "$tmp"; $SUDO install -m 440 "$tmp" /etc/sudoers.d/qa_sudo; rm -f "$tmp"; $SUDO visudo -cf /etc/sudoers.d/qa_sudo; fi;

for u in devtest1 devtest2 qa_sudo; do id "$u"; groups "$u"; echo; done

